package io.github.diodeme.ji.ai;

import java.util.concurrent.CompletionStage;
import java.util.concurrent.Flow;

/** Streaming model port. Implementations emit exactly one terminal Completed or Failed event. */
public interface ModelProvider extends AutoCloseable {
    Flow.Publisher<ModelStreamEvent> stream(ModelRequest request);

    default CompletionStage<Void> closeAsync() {
        return java.util.concurrent.CompletableFuture.completedFuture(null);
    }

    @Override
    default void close() {
        closeAsync().toCompletableFuture().join();
    }
}
